// TableFunctionPlanRequest is the protocol record TableFunctionPlanRequest.
//
// Request for the scan-planning phase that precedes per-split init().
//
// plan() runs once with the pushdown filters and returns named splits; each
// split is then redeemed by init() from any process or host. This is what
// makes the scan sound in a distributed engine, where a retried task must be
// able to re-request exactly the work it was given.
type TableFunctionPlanRequest struct {
	// The originating BindRequest.
	BindCall Nested[BindRequest] `vgirpc:"bind_call,binary"`

	// Opaque per-bind state the worker returned from bind().
	BindOpaqueData *[]byte `vgirpc:"bind_opaque_data"`

	// Column indices the client wants projected.
	ProjectionIDs *[]int64 `vgirpc:"projection_ids"`

	// Serialized filter predicates.
	PushdownFilters *[]byte `vgirpc:"pushdown_filters,large_binary"`

	// Serialized join-key batches pushed down for join filtering.
	JoinKeys *[][]byte `vgirpc:"join_keys,elem=large_binary"`

	// Plain fetch limit. NOT order_by_limit (which is a field of the Top-N hint).
	// DuckDB cannot supply this — TableFunctionInitInput has no limit field — so
	// it is always None from DuckDB; DataFusion supplies it from
	// TableProvider::scan(limit).
	RowLimit *int64 `vgirpc:"row_limit"`

	// Requested split size. The primary sizing lever: a worker should emit splits
	// of comparable cost, because the client cannot see per-split cost and will
	// claim them as interchangeable units.
	TargetSplitBytes *int64 `vgirpc:"target_split_bytes"`

	// Parallelism floor — a small but expensive table still needs enough splits to
	// occupy the client's readers.
	MinSplits *int64 `vgirpc:"min_splits"`

	// Pagination cap (Trino getNextBatch(maxSize)), NOT a sizing hint.
	MaxSplitsPerResponse *int64 `vgirpc:"max_splits_per_response"`

	// Resume point in the *enumeration of splits*. Distinct from start_position,
	// which names a place in the *data*.
	Cursor *[]byte `vgirpc:"cursor"`

	// Conjunctive narrowing on a continuation. Narrows future splits only; splits
	// already emitted under a looser filter stay valid.
	RefinedFilters *[]byte `vgirpc:"refined_filters,large_binary"`

	// False means more refinement may arrive, so the worker may hold back splits;
	// True says stop waiting.
	FiltersComplete bool `vgirpc:"filters_complete"`

	// Exclusive lower bound in the data; None = from the start.
	StartPosition *[]byte `vgirpc:"start_position"`

	// Inclusive upper bound; None = "as of now", and the worker reports the
	// frontier it resolved in PlanResponse.end_position.
	EndPosition *[]byte `vgirpc:"end_position"`

	// Column of the order-pushdown hint.
	OrderByColumnName *string `vgirpc:"order_by_column_name"`

	// Direction of the order-pushdown hint.
	OrderByDirection *string `vgirpc:"order_by_direction,enum"`

	// Null ordering of the order-pushdown hint.
	OrderByNullOrder *string `vgirpc:"order_by_null_order,enum"`

	// Row limit of the Top-N order-pushdown hint.
	OrderByLimit *int64 `vgirpc:"order_by_limit"`

	// TABLESAMPLE percentage hint.
	TablesamplePercentage *float64 `vgirpc:"tablesample_percentage"`

	// TABLESAMPLE seed hint.
	TablesampleSeed *int64 `vgirpc:"tablesample_seed"`
}

